'use strict';
const packet=JSON.parse(document.getElementById('packet-data').textContent);
const scene=packet.scene, state=CamModels.defaults(scene), audio=document.querySelector('audio');
let step=0,lang='or',cursor=.25,frame=null,lastTime=null;
const byId=id=>document.getElementById(id);
if(['flow','spectrum'].includes(scene.kind)){byId('motion').hidden=true;byId('cursor').parentElement.hidden=true;}
byId('title').textContent=packet.title;
function pauseMotion(){if(frame!==null)cancelAnimationFrame(frame);frame=null;lastTime=null;byId('motion').textContent='Play model cursor';}
function draw(){const r=CamModels.render(scene,state,cursor);byId('plots').replaceChildren();for(const p of r.plots){const figure=document.createElement('figure'),cap=document.createElement('figcaption');cap.textContent=p.label;figure.append(cap);const host=document.createElement('div');host.innerHTML=p.svg;figure.append(host);byId('plots').append(figure);}if(r.extraSvg){const host=document.createElement('div');host.innerHTML=r.extraSvg;byId('plots').append(host);}byId('readouts').replaceChildren();for(const [label,value] of r.readouts){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=value;byId('readouts').append(dt,dd);}byId('notes').textContent=r.notes.join(' ');byId('cursor').value=cursor;}
let activeAudio=null;
function showCard(){pauseMotion();const card=packet.placards[step];byId('card-title').textContent=card.title[lang==='en'?'en':'or'];byId('copy').textContent=lang==='en'?card.body.en:card.generatedMixed.displayText;byId('copy').lang=lang;byId('original').textContent=card.body.en;byId('position').textContent=`${step+1} / ${packet.placards.length}`;byId('back').disabled=step===0;byId('next').disabled=step===packet.placards.length-1;const clip=packet.narration.find(x=>x.placardId===card.id&&x.language===lang)||packet.narration.find(x=>x.scope==='concept'&&x.language===lang);if(clip){if(activeAudio!==clip.assetId){audio.pause();audio.src=clip.localFile;activeAudio=clip.assetId;}audio.hidden=false;byId('audio-label').textContent=clip.scope==='concept'?'Complete concept narration · manual placard navigation · unreviewed machine voice':'Placard narration · unreviewed machine voice · no sentence alignment';}else{audio.pause();audio.removeAttribute('src');audio.load();activeAudio=null;audio.hidden=true;byId('audio-label').textContent='No matching narration for this language; text remains available.';}}
for(const control of scene.controls){const label=document.createElement('label');label.textContent=control.label+(control.unit?' ('+control.unit+')':'');const input=document.createElement('input');input.type='range';input.min=control.min;input.max=control.max;input.step=control.step;input.value=control.default;input.dataset.parameter=control.name;const output=document.createElement('output');output.textContent=control.default;input.addEventListener('input',()=>{audio.pause();pauseMotion();state[control.name]=Number(input.value);output.textContent=input.value;draw();});label.append(input,output);byId('parameters').append(label);}
byId('back').onclick=()=>{if(step>0){step--;showCard();}};byId('next').onclick=()=>{if(step<packet.placards.length-1){step++;showCard();}};
byId('language').onchange=e=>{lang=e.target.value;showCard();};byId('reset').onclick=()=>{audio.pause();pauseMotion();Object.assign(state,CamModels.defaults(scene));for(const input of document.querySelectorAll('[data-parameter]')){input.value=state[input.dataset.parameter];input.nextElementSibling.textContent=input.value;}cursor=.25;draw();};
byId('cursor').oninput=e=>{audio.pause();pauseMotion();cursor=Number(e.target.value);draw();};
byId('motion').onclick=()=>{audio.pause();if(frame!==null){pauseMotion();return;}byId('motion').textContent='Pause model cursor';const tick=t=>{if(lastTime!==null)cursor=(cursor+Math.min(t-lastTime,100)/8000)%1;lastTime=t;draw();frame=requestAnimationFrame(tick);};frame=requestAnimationFrame(tick);};
audio.addEventListener('play',pauseMotion);document.addEventListener('visibilitychange',()=>{if(document.hidden){audio.pause();pauseMotion();}});window.addEventListener('pagehide',()=>{audio.pause();pauseMotion();});
showCard();draw();
